-- PR-12 TEST source expansion: wine, beer and premium toy brands.
-- Idempotent; all entries remain da_verificare until runtime checks are completed.
insert into collection.registro_fonti
(nome,url_base,ambito,categoria,marchio_editore,franchise,mercato,tipo_fonte,priorita,attendibilita_dichiarata,stato_verifica,origine_configurazione,condivisa,attiva,note)
select v.nome,v.url_base,v.ambito,v.categoria,v.marchio_editore,v.franchise,v.mercato,v.tipo_fonte,v.priorita,v.attendibilita_dichiarata,'da_verificare','sistema',true,true,v.note
from (values
('Untappd','https://untappd.com/','catalogo birre e check-in','birre e birre da collezione','Untappd','birre artigianali; birre internazionali','globale','specialistica',2,'alta','Schede birra, birrifici e varianti; prezzi non sempre disponibili'),
('BeerAdvocate','https://www.beeradvocate.com/','catalogo e recensioni','birre e birre da collezione','BeerAdvocate','birre internazionali','globale','specialistica',2,'alta','Schede, produttori e valutazioni della community; non equivale a prezzo realizzato'),
('RateBeer','https://www.ratebeer.com/','catalogo e recensioni','birre e birre da collezione','RateBeer','birre internazionali','globale','specialistica',3,'media','Fonte complementare per identificare birre e birrifici'),
('BeerMenus','https://www.beermenus.com/','catalogo e disponibilità','birre e birre da collezione','BeerMenus','birre artigianali','globale','specialistica',4,'media','Utile per nomi, produttori e confezioni; prezzi riferiti alla vendita corrente'),
('Wine-Searcher','https://www.wine-searcher.com/','catalogo e confronto prezzi','vino e bottiglie pregiate','Wine-Searcher','vini; annate; formati','globale','mercato',1,'alta','Prezzi richiesti da rivenditori e disponibilità; distinguere quotazione da vendita conclusa'),
('Vivino','https://www.vivino.com/','identificazione vino e annata','vino e bottiglie pregiate','Vivino','vini; cantine; annate','globale','specialistica',2,'alta','Schede vino, produttore, denominazione e annata; prezzi da verificare per formato e mercato'),
('CellarTracker','https://www.cellartracker.com/','database bottiglie e annate','vino e bottiglie pregiate','CellarTracker','vini da collezione; annate','globale','specialistica',2,'alta','Archivio vino e note degli utenti; valori non sempre rappresentano transazioni'),
('Decanter','https://www.decanter.com/','guide e valutazioni editoriali','vino e bottiglie pregiate','Decanter','vini; cantine; annate','globale','specialistica',3,'alta','Riscontro editoriale su produttori, annate e qualità'),
('Wine Spectator','https://www.winespectator.com/','database e valutazioni editoriali','vino e bottiglie pregiate','Wine Spectator','vini; annate','globale','specialistica',3,'alta','Schede e punteggi editoriali, non prova del valore di mercato'),
('Liv-ex','https://www.liv-ex.com/','mercato fine wine','vino e bottiglie pregiate','Liv-ex','fine wine; vini da investimento','globale','mercato',1,'alta','Riferimento specializzato per fine wine; accesso e dati possono essere limitati'),
('Consorzio Barolo Barbaresco Alba Langhe Dogliani','https://www.langhevini.it/','denominazioni e produttori','vino e bottiglie pregiate','Consorzio di tutela','Barolo; Barbaresco; Langhe','Italia','ufficiale',2,'ufficiale','Riscontro su denominazioni e produttori, non quotazioni di mercato'),
('Consorzio Brunello di Montalcino','https://www.consorziobrunellodimontalcino.it/','denominazioni e produttori','vino e bottiglie pregiate','Consorzio Brunello di Montalcino','Brunello di Montalcino','Italia','ufficiale',2,'ufficiale','Riscontro ufficiale per produttori e denominazione'),
('Consorzio del Vino Nobile di Montepulciano','https://www.consorziovinonobile.it/','denominazioni e produttori','vino e bottiglie pregiate','Consorzio Vino Nobile','Vino Nobile di Montepulciano','Italia','ufficiale',3,'ufficiale','Riscontro ufficiale per denominazione e produttori'),
('Mattel','https://shop.mattel.com/pages/all-brands','catalogo produttore','giocattoli da collezione','Mattel','Barbie; Hot Wheels; Matchbox; Masters of the Universe','globale','ufficiale',1,'ufficiale','Fonte primaria per marchi, linee e prodotti'),
('Hasbro Pulse','https://www.hasbropulse.com/eu/it/','catalogo produttore','giocattoli da collezione','Hasbro','Transformers; G.I. Joe; Marvel Legends; Star Wars','Europa','ufficiale',1,'ufficiale','Fonte primaria per linee e referenze recenti'),
('Takara Tomy','https://www.takaratomy.co.jp/','catalogo produttore','giocattoli da collezione','Takara Tomy','Tomica; Transformers; Licca; Beyblade','Giappone','ufficiale',1,'ufficiale','Fonte primaria per prodotti e referenze giapponesi'),
('Playmobil','https://www.playmobil.com/','catalogo produttore','giocattoli da collezione','Playmobil','Playmobil','globale','ufficiale',1,'ufficiale','Catalogo ufficiale per codici e linee'),
('Schleich','https://www.schleich-s.com/','catalogo produttore','giocattoli da collezione','Schleich','animali; fantasy; personaggi','globale','ufficiale',2,'ufficiale','Catalogo ufficiale per identificazione delle figure'),
('Fisher-Price','https://www.fisher-price.com/','catalogo produttore','giocattoli da collezione','Mattel','Fisher-Price vintage','globale','ufficiale',2,'ufficiale','Riferimento produttore per linee e giocattoli storici'),
('The Toy Collector','https://www.thetoycollector.com/','catalogo e identificazione vintage','giocattoli da collezione','The Toy Collector','giocattoli vintage','globale','specialistica',3,'media','Fonte complementare; verificare copertura e corrispondenza'),
('Transformerland','https://www.transformerland.com/','catalogo e mercato vintage','giocattoli da collezione','Transformerland','Transformers vintage','globale','mercato',2,'alta','Catalogo specialistico per identificazione e prezzi richiesti'),
('The Old Toy Guide','https://www.theoldtoyguide.com/','catalogo vintage','giocattoli da collezione','The Old Toy Guide','giocattoli vintage','globale','specialistica',3,'media','Fonte di supporto per identificazione di giocattoli d’epoca')
) as v(nome,url_base,ambito,categoria,marchio_editore,franchise,mercato,tipo_fonte,priorita,attendibilita_dichiarata,note)
where not exists (select 1 from collection.registro_fonti f where lower(f.nome)=lower(v.nome) and f.url_base=v.url_base);
